import React, { useEffect, useState } from 'react';
import api from '../api';

// Ce composant affiche le détail d'un document, avec le bouton "Signer"
// visible seulement pour un responsable, et seulement si le document
// n'est pas déjà signé.
function DocumentDetail({ documentId, user, onRetour }) {
    const [document, setDocument] = useState(null);
    const [message, setMessage] = useState('');

    const chargerDocument = async () => {
        try {
            const reponse = await api.get(`/documents/${documentId}`);
            setDocument(reponse.data);
        } catch (err) {
            console.error(err);
        }
    };

    // On charge le document quand le composant s'affiche
    useEffect(() => {
        chargerDocument();
    }, [documentId]);

    // Appelé quand le responsable clique sur le bouton "Signer"
    const handleSigner = async () => {
        try {
            await api.post('/signatures', {
                document_id: document.id,
                user_id: user.id,
                nom_signataire: `${user.prenom} ${user.nom}`,
                role: user.role
            });

            setMessage('Document signé avec succès !');
            chargerDocument(); // on recharge le document pour voir le nouveau statut

        } catch (err) {
            console.error(err);
            setMessage('Erreur lors de la signature.');
        }
    };

    if (!document) {
        return <div className="container">Chargement...</div>;
    }

    return (
        <div className="container" style={{ maxWidth: '600px' }}>
            <button className="btn btn-secondary btn-sm mb-3" onClick={onRetour}>
                ← Retour à la liste
            </button>

            <div className="card p-4 shadow-sm">
                <h3>{document.titre}</h3>
                <p className="text-muted">
                    Créé par {document.auteur_prenom} {document.auteur_nom} le{' '}
                    {new Date(document.date_creation).toLocaleString()}
                </p>

                <p>{document.description}</p>

                <p>
                    Statut :{' '}
                    {document.statut === 'signe' ? (
                        <span className="badge bg-success">Signé</span>
                    ) : (
                        <span className="badge bg-warning text-dark">En attente</span>
                    )}
                </p>

                {/* Lien pour ouvrir le fichier PDF dans un nouvel onglet */}
                <a
                    className="btn btn-outline-primary mb-3"
                    href={`http://localhost:5000/uploads/${document.fichier_pdf}`}
                    target="_blank"
                    rel="noreferrer"
                >
                    📄 Voir le fichier PDF
                </a>

                {message && <div className="alert alert-info">{message}</div>}

                {/* Le bouton Signer n'apparaît que pour un responsable,
                    et seulement si le document n'est pas encore signé */}
                {user.role === 'responsable' && document.statut === 'en_attente' && (
                    <button className="btn btn-success" onClick={handleSigner}>
                        ✔️ Signer ce document
                    </button>
                )}
            </div>
        </div>
    );
}

export default DocumentDetail;
